// Use this instead of wrapping ScopeTenant in an anonymous function:
//
//	q.Apply(factoringcol.NoaApplyTenant(tenantInfo))
func NoaApplyTenant(ti pagination.TenantInfo) func(*bun.SelectQuery) *bun.SelectQuery {
	return buncolgen.ApplyTenant(NoaColumns.OrganizationID, NoaColumns.BusinessUnitID, ti)
}

